"""Independent statistical analysis of games 1-45: field structure, estimate quality,
charge/accept sweeps against the real field, P(fair | charge) curve, fraud payout check,
and the backtest's 'expected' decomposition."""
import json, math, sys, collections, statistics
from pathlib import Path
ROOT = Path(r"c:/Users/Admin/Desktop/TUM/8.Semester/Hackathon/EHL-Hackathon-template-repo")
sys.path.insert(0, str(ROOT))
from c2f.feedback import digest
from c2f.backtest import t_bounds, score
from c2f import price as P
from c2f.extract import case_labels, load_case

US = "AsianSuperNerds"
INF = float("inf")
cal = P.calibration()
print("calibration in effect:", {k: v for k, v in cal.__dict__.items() if k != 'bias_by_bucket'})
print("buckets:", cal.bias_by_bucket)
print("price constants: A_MAX_Q", P.A_MAX_Q, "B_QUANTILE", round(P.B_QUANTILE, 4), "RISK_AVERSION", P.RISK_AVERSION,
      "UNCOVERED_CHARGE", P.UNCOVERED_CHARGE, "FRAUD_PAYOUT_FRAC", P.FRAUD_PAYOUT_FRAC)


def replay_items(g):
    p = ROOT / "runs" / "backtest" / f"game_{g:02d}.json"
    if not p.exists():
        return {}
    rep = json.loads(p.read_text())["replay"]
    out = rep.get("estimate") or rep.get("ensemble")
    if not out:
        return {}
    items = {int(it["index"]): dict(it) for it in out["items"]}
    try:
        descs = case_labels(load_case(ROOT / "cases" / f"case_{g:02d}", g))
    except Exception:
        descs = {}
    for i, it in items.items():
        if not it.get("_description"):
            it["_description"] = descs.get(i, "")
    return items


GAMES = [g for g in range(1, 46) if (ROOT / "runs" / f"truth_game_{g:02d}.json").exists() and (ROOT / "runs" / "backtest" / f"game_{g:02d}.json").exists()]
NEW_PROMPT = [g for g in GAMES if g == 16 or g >= 34]
WINDOW = [g for g in GAMES if g >= 36]
print("games with truth+replay:", GAMES)
print("new-prompt games:", NEW_PROMPT, " window:", WINDOW)

D = {}
EST = {}
for g in GAMES:
    d = digest(g)
    t_bounds(g, d)
    D[g] = d
    EST[g] = replay_items(g)

# ------------------------------------------------------------------ 1. field structure
print("\n=== 1. THE FIELD: what opponents charge, relative to proven t ===")


def field_stats(games, label):
    n_fair = n_fraud = n_open = 0
    v_fair = v_fraud = v_open = 0.0
    acc_fair = []
    acc_fraud = []
    for g in games:
        d = D[g]
        for i in d["items"]:
            lo, hi = d["t_lo"][i], d["t_hi"][i]
            for j in d["teams"]:
                if j == US:
                    continue
                a = d["issued"][j].get(i)
                if not a:
                    continue
                f = d["fair"][j].get(i)
                if f is None:
                    f = True if a <= lo + 1e-9 else (False if a >= hi - 1e-9 else None)
                acc = d["accepted"][j][i]
                if f is True:
                    n_fair += 1
                    v_fair += a
                    if acc:
                        acc_fair.append(sum(acc) / len(acc))
                elif f is False:
                    n_fraud += 1
                    v_fraud += a
                    if acc:
                        acc_fraud.append(sum(acc) / len(acc))
                else:
                    n_open += 1
                    v_open += a
    tot = n_fair + n_fraud + n_open
    print(f"[{label}] opponent charges: {tot}  fair {n_fair} ({n_fair/tot:.0%})  fraud {n_fraud} ({n_fraud/tot:.0%})  open {n_open} ({n_open/tot:.0%})")
    vt = v_fair + v_fraud + v_open
    print(f"     by value: fair {v_fair/vt:.0%}  fraud {v_fraud/vt:.0%}  open {v_open/vt:.0%}   (fair:fraud value ratio {v_fair/max(v_fraud,1):.1f}:1)")
    if acc_fair:
        print(f"     mean accept rate of proven-FAIR charges {statistics.mean(acc_fair):.2f}; of proven-FRAUD charges {statistics.mean(acc_fraud):.2f}")


field_stats(GAMES, "all 1-45")
field_stats(NEW_PROMPT, "16,34-45")
field_stats(WINDOW, "36-45")

# ------------------------------------------------------------------ 2. estimate quality
print("\n=== 2. OUR ESTIMATES vs the proven bracket (replay estimates, covered items) ===")


def est_quality(games, label, transform=None):
    under = over = inside = 0
    under_lr = []
    over_lr = []
    miss_cov = 0
    miss_cov_val = 0.0
    false_cov = 0
    for g in games:
        d = D[g]
        for i, it in EST[g].items():
            if i not in d["t_lo"]:
                continue
            lo, hi = d["t_lo"][i], d["t_hi"][i]
            cov = bool(it.get("covered")) and bool(it.get("related", True))
            mid = sorted(P._num(it.get(k)) for k in ("t_low", "t_mid", "t_high"))[1]
            if not cov:
                if lo > 0:
                    miss_cov += 1
                    miss_cov_val += lo
                continue
            if mid <= 0:
                continue
            if lo <= 0 and hi < INF and hi < 0.5 * mid:
                false_cov += 1
            if lo <= 0 and hi == INF:
                continue
            x = transform(it) if transform else mid
            if x < lo:
                under += 1
                under_lr.append(math.log(lo / x))
            elif hi < INF and x >= hi:
                over += 1
                over_lr.append(math.log(x / hi))
            else:
                inside += 1
    n = under + over + inside
    med = lambda v: statistics.median(v) if v else 0
    print(f"[{label}] n={n}: below bracket {under} ({under/n:.0%}, median gap x{math.exp(med(under_lr)):.2f}) | inside {inside} ({inside/n:.0%}) | above bracket {over} ({over/n:.0%}, median gap x{math.exp(med(over_lr)):.2f}) | said-uncovered-but-t>0: {miss_cov} (sum t_lo {miss_cov_val:.0f}) | said-covered-but-t~0: {false_cov}")


for label, games in (("all", GAMES), ("new-prompt", NEW_PROMPT), ("36-45", WINDOW)):
    est_quality(games, label + " raw t_mid")
    est_quality(games, label + " calibrated median", lambda it: P.Belief.from_estimate(it, cal).median)
    est_quality(games, label + " b=Q(1/3)", lambda it: P.Belief.from_estimate(it, cal).quantile(1 / 3))

# ------------------------------------------------------------------ 3. sweeps
print("\n=== 3. SWEEPS against the real field (income depends on a only, cost on b only) ===")


def rows_for(g, a_rule, b_rule):
    rows = []
    d = D[g]
    for i in d["items"]:
        it = EST[g].get(i)
        if not it:
            rows.append({"index": i, "charge_price": 0.0, "acceptance_limit": 0.0})
            continue
        cov = bool(it.get("covered")) and bool(it.get("related", True))
        mid = sorted(P._num(it.get(k)) for k in ("t_low", "t_mid", "t_high"))[1]
        if not cov or mid <= 0:
            guess = P._num(it.get("t_if_covered")) or mid
            rows.append({"index": i, "charge_price": round(P.UNCOVERED_CHARGE * cal.bias_for(it.get("_description")) * guess, 2), "acceptance_limit": 0.0})
            continue
        bel = P.Belief.from_estimate(it, cal)
        rows.append({"index": i, "charge_price": a_rule(bel, it), "acceptance_limit": b_rule(bel, it)})
    return rows


def total(games, a_rule, b_rule):
    inc = {"pessimistic": 0.0, "optimistic": 0.0}
    cost = {"pessimistic": 0.0, "optimistic": 0.0}
    per_game = {}
    for g in games:
        sc = score(g, rows_for(g, a_rule, b_rule), D[g], US)
        for s in inc:
            inc[s] += sc["scenarios"][s]["income"]
            cost[s] += sc["scenarios"][s]["cost"]
        per_game[g] = sc
    return inc, cost, per_game


def code_a(bel, it):
    return P.best_charge(bel, cal)


def code_b(bel, it):
    b = P.accept_limit(bel)
    if bel.median >= P.WHALE_T:
        b = max(b, bel.median)
    return b


def zero(bel, it):
    return 0.0


raw = P.Calibration()
for label, games in (("36-45", WINDOW), ("new-prompt 16,34-45", NEW_PROMPT), ("all 1-45", GAMES)):
    print(f"\n--- [{label}] CHARGE a = Q(q) of calibrated belief; income pess / opt (midpoint) ---")
    for q in (0.2, 0.3, 0.4, 0.5, 0.55, 0.6, 0.65, 0.7, 0.8, 0.9):
        inc, _, _ = total(games, lambda bel, it, q=q: bel.quantile(q), zero)
        print(f"  a=Q({q:.2f}): income pess {inc['pessimistic']:9.0f}  opt {inc['optimistic']:9.0f}  mid {(inc['pessimistic']+inc['optimistic'])/2:9.0f}")
    for m in (0.6, 0.8, 1.0):
        inc, _, _ = total(games, lambda bel, it, m=m: m * bel.median, zero)
        print(f"  a={m:.1f}*median: income pess {inc['pessimistic']:9.0f}  opt {inc['optimistic']:9.0f}  mid {(inc['pessimistic']+inc['optimistic'])/2:9.0f}")
    inc, _, _ = total(games, code_a, zero)
    print(f"  a=CODE best_charge: income pess {inc['pessimistic']:9.0f}  opt {inc['optimistic']:9.0f}  mid {(inc['pessimistic']+inc['optimistic'])/2:9.0f}")
    for q in (0.4, 0.5, 0.6):
        inc, _, _ = total(games, lambda bel, it, q=q: P.Belief.from_estimate(it, raw).quantile(q), zero)
        print(f"  a=Q({q:.2f}) of RAW t_mid belief (bias 1): income pess {inc['pessimistic']:9.0f}  opt {inc['optimistic']:9.0f}  mid {(inc['pessimistic']+inc['optimistic'])/2:9.0f}")

    print(f"--- [{label}] ACCEPT b = Q(q) of calibrated belief; cost pess / opt (lower is better) ---")
    for q in (0.2, 1 / 3, 0.4, 0.5, 0.6, 0.7, 0.8, 0.9, 0.95):
        _, cost, _ = total(games, zero, lambda bel, it, q=q: bel.quantile(q))
        print(f"  b=Q({q:.2f}): cost pess {cost['pessimistic']:9.0f}  opt {cost['optimistic']:9.0f}  mid {(cost['pessimistic']+cost['optimistic'])/2:9.0f}")
    for m in (1.0, 1.5, 2.0, 3.0, 1e9):
        _, cost, _ = total(games, zero, lambda bel, it, m=m: m * bel.median)
        print(f"  b={m:.1f}*median: cost pess {cost['pessimistic']:9.0f}  opt {cost['optimistic']:9.0f}  mid {(cost['pessimistic']+cost['optimistic'])/2:9.0f}")
    _, cost, _ = total(games, zero, code_b)
    print(f"  b=CODE (Q(1/3)+whale floor): cost pess {cost['pessimistic']:9.0f}  opt {cost['optimistic']:9.0f}  mid {(cost['pessimistic']+cost['optimistic'])/2:9.0f}")
    for name, bval in (("ACCEPT EVERYTHING (incl. uncovered)", 1e9), ("REJECT EVERYTHING", 0.0)):
        c = {"pessimistic": 0.0, "optimistic": 0.0}
        for g in games:
            sc = score(g, [{"index": i, "charge_price": 0.0, "acceptance_limit": bval} for i in D[g]["items"]], D[g], US)
            for s in c:
                c[s] += sc["scenarios"][s]["cost"]
        print(f"  b={name}: cost pess {c['pessimistic']:9.0f}  opt {c['optimistic']:9.0f}")

# ------------------------------------------------------------------ 4. P(fair | charge ratio)
print("\n=== 4. P(fair | opponent charge / our calibrated median) - the number b should threshold at 2/3 ===")


def pfair(games, label):
    bins = collections.defaultdict(lambda: [0, 0, 0, 0.0, 0.0, 0.0])
    edges = [0, 0.25, 0.5, 0.75, 1.0, 1.25, 1.5, 2.0, 3.0, 1e9]
    for g in games:
        d = D[g]
        for i, it in EST[g].items():
            if i not in d["t_lo"]:
                continue
            cov = bool(it.get("covered")) and bool(it.get("related", True))
            mid = sorted(P._num(it.get(k)) for k in ("t_low", "t_mid", "t_high"))[1]
            if not cov or mid <= 0:
                continue
            m = P.Belief.from_estimate(it, cal).median
            lo, hi = d["t_lo"][i], d["t_hi"][i]
            for j in d["teams"]:
                if j == US:
                    continue
                a = d["issued"][j].get(i)
                if not a:
                    continue
                f = d["fair"][j].get(i)
                if f is None:
                    f = True if a <= lo + 1e-9 else (False if a >= hi - 1e-9 else None)
                r = a / m
                key = None
                for k in range(len(edges) - 1):
                    if edges[k] <= r < edges[k + 1]:
                        key = (edges[k], edges[k + 1])
                        break
                b = bins[key]
                if f is True:
                    b[0] += 1
                    b[3] += a
                elif f is False:
                    b[1] += 1
